+import { StorageManagementClient } from "@azure/arm-storage";
+import { DefaultAzureCredential } from "@azure/identity";
+
+function requireEnvironmentVariable(name: string): string {
+  const value = process.env[name];
+  if (!value) {
+    throw new Error(`Missing required environment variable: ${name}`);
+  }
+
+  return value;
+}
+
+async function main(): Promise<void> {
+  const subscriptionId = requireEnvironmentVariable("AZURE_SUBSCRIPTION_ID");
+  const resourceGroupName = requireEnvironmentVariable("AZURE_RESOURCE_GROUP");
+  const accountName = requireEnvironmentVariable("AZURE_STORAGE_ACCOUNT_NAME");
+
+  const credential = new DefaultAzureCredential();
+  const client = new StorageManagementClient(credential, subscriptionId);
+  let accountCreated = false;
+
+  try {
+    console.log(`Creating storage account "${accountName}"...`);
+    const account = await client.storageAccounts.beginCreateAndWait(
+      resourceGroupName,
+      accountName,
+      {
+        location: "eastus",
+        kind: "StorageV2",
+        sku: { name: "Standard_LRS" },
+      },
+    );
+    accountCreated = true;
+    console.log(`Created: ${account.id}`);
+
+    console.log(`Storage accounts in resource group "${resourceGroupName}":`);
+    for await (const storageAccount of client.storageAccounts.listByResourceGroup(
+      resourceGroupName,
+    )) {
+      console.log(`- ${storageAccount.name} (${storageAccount.location})`);
+    }
+
+    const properties = await client.storageAccounts.getProperties(
+      resourceGroupName,
+      accountName,
+    );
+    console.log("Created account properties:", {
+      id: properties.id,
+      name: properties.name,
+      location: properties.location,
+      provisioningState: properties.provisioningState,
+      primaryEndpoints: properties.primaryEndpoints,
+    });
+
+    await client.blobServices.setServiceProperties(
+      resourceGroupName,
+      accountName,
+      "default",
+      { isVersioningEnabled: true },
+    );
+    console.log("Blob versioning enabled.");
+  } finally {
+    if (accountCreated) {
+      console.log(`Deleting storage account "${accountName}"...`);
+      await client.storageAccounts.beginDeleteAndWait(
+        resourceGroupName,
+        accountName,
+      );
+      console.log("Storage account deleted.");
+    }
+  }
+}
+
+main().catch((error: unknown) => {
+  console.error("Storage account management failed:", error);
+  process.exitCode = 1;
+});
*** Add File: README.md
+# Azure Storage account management with TypeScript
+
+This example uses the Azure management-plane SDK to create, list, inspect,
+update, and delete a StorageV2 account. The resource group must already exist.
+The account name must be globally unique, 3-24 characters long, and contain
+only lowercase letters and numbers.
+
+## Install
+
+```powershell
+npm install
+```
+
+The required runtime packages are:
+
+```powershell
+npm install @azure/arm-storage @azure/identity
+```
+
+## Configure and run
+
+Set the variables shown in `.env.example` in your shell, authenticate with a
+developer credential supported by `DefaultAzureCredential`, and run:
+
+```powershell
+$env:AZURE_SUBSCRIPTION_ID = "<subscription-id>"
+$env:AZURE_RESOURCE_GROUP = "<existing-resource-group>"
+$env:AZURE_STORAGE_ACCOUNT_NAME = "<globally-unique-name>"
+npm start
+```
+
+The program deletes the account in a `finally` block after the other operations
+finish. `DefaultAzureCredential` is convenient for local development; prefer a
+specific managed identity credential for Azure-hosted production applications.
+
+Reference:
+[Azure Storage management client library for JavaScript](https://learn.microsoft.com/javascript/api/overview/azure/arm-storage-readme)
